from fastapi.dependencies.models import Dependant
import asyncio
import inspect

class MyDep:
    async def __call__(self):
        return "hello"

def test_coroutine_callable():
    dep = Dependant(call=MyDep)
    print(f"MyDep is_coroutine_callable: {dep.is_coroutine_callable}")
    assert dep.is_coroutine_callable is False

class MyGenDep:
    def __call__(self):
        yield "hello"

def test_gen_callable():
    dep = Dependant(call=MyGenDep)
    print(f"MyGenDep is_gen_callable: {dep.is_gen_callable}")
    assert dep.is_gen_callable is False

class MyAsyncGenDep:
    async def __call__(self):
        yield "hello"

def test_async_gen_callable():
    dep = Dependant(call=MyAsyncGenDep)
    print(f"MyAsyncGenDep is_async_gen_callable: {dep.is_async_gen_callable}")
    assert dep.is_async_gen_callable is False

if __name__ == "__main__":
    try:
        test_coroutine_callable()
        print("test_coroutine_callable passed")
    except AssertionError as e:
        print("test_coroutine_callable failed")

    try:
        test_gen_callable()
        print("test_gen_callable passed")
    except AssertionError as e:
        print("test_gen_callable failed")

    try:
        test_async_gen_callable()
        print("test_async_gen_callable passed")
    except AssertionError as e:
        print("test_async_gen_callable failed")

